import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { BUBBLE_TOP, CARD, EFFORTS, MODELS, isActiveModel, isEffort } from './panel'

const model = atom({ plugin: 'gauravs-panel', key: 'model' } as const, null)
// Effort has no getter in the API: it is seeded from the last model request
// (turn.step carries it) and set optimistically when a button is pressed.
const effort = atom({ plugin: 'gauravs-panel', key: 'effort' } as const, null)
// Whether the card is showing.
const isOpen = atom({ plugin: 'gauravs-panel', key: 'isOpen' } as const, false)
// Panes on screen (any plugin's). While one is up it paints over the rows
// above the footer, so the card moves into that pane and draws on top there.
const panes = atom({ plugin: 'gauravs-panel', key: 'panes' } as const, [] as string[])

async function refreshModel($: EngineInterface) {
  const current = await $.session.model()
  await update($, model, () => current)
}

// A pick closes the card first, then runs the real command.
async function pick($: EngineInterface, command: 'model' | 'effort', arg: string) {
  await update($, isOpen, () => false)
  try {
    // Show what the command said, so a refused switch is never silent.
    const { text } = await $.command.run({ command, args: arg })
    if (text) $.ui.toast(text)
    if (command === 'model') await refreshModel($)
    else await update($, effort, () => (isEffort(arg) ? arg : null))
  } catch {
    $.ui.toast(`Could not set ${command} to ${arg}`)
  }
}

// The two-row card, absolutely placed. Callers put it LAST among their
// children: there is no z-index, and an absolute Box paints only over the
// siblings before it.
async function card($: EngineInterface, e: Parameters<EngineInterface['ui']['resolve']>[0], top: number) {
  const current = await read($, model)
  const level = await read($, effort)
  const { Box, Text, Button } = $.ui.resolve(e)

  const row = (
    label: string,
    items: Array<{ key: string; label: string; isActive: boolean; onPress: () => void }>,
  ) => (
    <Box flexDirection="row">
      <Box width={12}>
        <Text color={CARD.label}>{label}</Text>
      </Box>
      {items.map(item => (
        <Box
          key={`box-${item.key}`}
          paddingX={2}
          backgroundColor={item.isActive ? CARD.lit : undefined}
        >
          <Button key={item.key} label={item.label} plain onPress={item.onPress} />
        </Box>
      ))}
    </Box>
  )

  return (
    <Box
      position="absolute"
      top={top}
      right={0}
      flexDirection="column"
      paddingX={2}
      backgroundColor={CARD.bubble}
    >
      {row(
        'MODEL',
        MODELS.map(c => ({
          key: c.key,
          label: c.label,
          isActive: isActiveModel(current, c),
          onPress: () => pick($, 'model', c.arg),
        })),
      )}
      {row(
        'EFFORT',
        EFFORTS.map(c => ({
          key: c.level,
          label: c.label,
          isActive: level === c.level,
          onPress: () => pick($, 'effort', c.level),
        })),
      )}
    </Box>
  )
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    // An earlier version pinned a text readout under the prompt; clear it.
    $.ui.status(undefined)
    await $.command.register({
      name: 'panel',
      description: "Gaurav's Tools: pick the model and effort in one click",
      immediate: true,
    })
    await refreshModel($)
    return result
  })

  on('command.run', { command: 'panel' }, async $ => {
    await update($, isOpen, open => !open)
    return { text: "Gaurav's Tools toggled." }
  })

  on('turn.complete', async ($, e, next) => {
    await refreshModel($)
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (isEffort(e.effort)) {
      const seen = e.effort
      await update($, effort, () => seen)
    }
    return yield* next(e)
  })

  // A pane that opens takes the card over from the footer.
  on('ui.open', async ($, e, next) => {
    const result = await next(e)
    const id = e.id
    if ('value' in result && result.value?.isPlaced) await update($, panes, ids => (ids.includes(id) ? ids : [...ids, id]))
    return result
  })

  // A pane that closes hands the card back to the footer.
  on('ui.close', async ($, e, next) => {
    const result = await next(e)
    const id = e.id
    await update($, panes, ids => ids.filter(p => p !== id))
    return result
  })

  // Every pane: keep what its owner drew and lay the card over its last two
  // visible rows. This needs gauravs-panel ABOVE the pane's owner in the chain
  // (first in CLAUDE_CODE_PLUGIN_DIRS), since an owner's hook doesn't call next.
  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    const below = await next(e)
    if (!(await read($, isOpen))) return below
    const { Box } = $.ui.resolve(e)
    const { offset, bodyRows } = e.props.scroll
    return (
      <Box flexDirection="column">
        {below}
        {await card($, e, offset + Math.max(0, bodyRows - 2))}
      </Box>
    )
  })

  // The right end of the prompt footer: keep the engine's mode labels, add the
  // button, and draw the card over the rows above it while no pane is up.
  on('ui.render', { component: 'SessionMode' }, async ($, e) => {
    const open = await read($, isOpen)
    const paneUp = (await read($, panes)).length > 0
    const { Box, Text, Button } = $.ui.resolve(e)
    const modes = e.props.modes

    return (
      <Box flexDirection="row">
        {modes.length > 0 ? <Text dimColor>{modes.join(' & ')} </Text> : null}
        <Box key="open-box" paddingX={1} backgroundColor={CARD.button}>
          <Button
            key="open"
            label={open ? "◆ Gaurav's Tools ▲" : "◆ Gaurav's Tools ▼"}
            plain
            hover={{ color: '#ffffff', backgroundColor: CARD.hover, bold: true }}
            onPress={() => update($, isOpen, o => !o)}
          />
        </Box>
        {open && !paneUp ? await card($, e, BUBBLE_TOP) : null}
      </Box>
    )
  })
}

