import type { Effort } from '../types'

export type ModelChoice = { key: string; label: string; arg: string; match: string }
export type EffortChoice = { level: Effort; label: string }

// `arg` is what /model is given; `match` finds the choice in the resolved id
// that $.session.model() returns (e.g. claude-opus-5-5).
export const MODELS: ModelChoice[] = [
  { key: 'haiku', label: 'Haiku 4.5', arg: 'haiku', match: 'haiku' },
  { key: 'sonnet', label: 'Sonnet 5.5', arg: 'sonnet', match: 'sonnet' },
  { key: 'opus', label: 'Opus 5.5', arg: 'opus', match: 'opus' },
  { key: 'fable', label: 'Fable 5.1', arg: 'claude-fable-5-1', match: 'fable' },
]

export const EFFORTS: EffortChoice[] = [
  { level: 'low', label: 'Low' },
  { level: 'medium', label: 'Medium' },
  { level: 'high', label: 'High' },
  { level: 'xhigh', label: 'XHigh' },
  { level: 'max', label: 'Max' },
]

export const isActiveModel = (current: string | null, choice: ModelChoice) =>
  current !== null && current.toLowerCase().includes(choice.match)

export const isEffort = (value: unknown): value is Effort =>
  typeof value === 'string' && EFFORTS.some(c => c.level === value)

// Claude's own colour only: its terracotta orange lights the chosen option on
// both rows, everything else stays neutral.
export const CARD = {
  // Match the terminal's own background so the card reads as transparent.
  bubble: '#282c34',
  label: '#8a8678',
  lit: '#d97757',
  // The footer button wears the same Claude terracotta, a shade lighter under the pointer.
  button: '#d97757',
  hover: '#e8906f',
}

// The footer slot paints only rows 4, 3 and 2 above the footer line; anything
// higher is cut off (confirmed on screen, and again at -14). The card is two
// rows, so it starts at the very top of that window.
export const BUBBLE_TOP = -4

